 const sails=[];for(const [z,h,w]of [[.65,6.7,3.7],[-1.65,5.5,2.8]]){cylinder(ship,.065,.12,h,palette.wood,0,h/2+1,z,8);for(let k=0;k<2;k++){const yy=h-1.5-k*1.8;const width=w*(k===0?.8:1);const spar=cylinder(ship,.045,.045,width+ .5,palette.wood,0,yy+1.1,z,6);spar.rotation.z=Math.PI/2;const points=[],ix=[],uv=[];const nx=12,ny=10;for(let y=0;y<=ny;y++)for(let x=0;x<=nx;x++){const u=x/nx,v=y/ny;points.push((u-.5)*width,yy+1.1-v*1.65,z+.08+Math.sin(u*Math.PI)*Math.sin(v*Math.PI)*.65);uv.push(u,1-v);if(x<nx&&y<ny){const a=y*(nx+1)+x;ix.push(a,a+1,a+nx+1,a+1,a+nx+2,a+nx+1);}}const sg=new THREE.BufferGeometry();sg.setAttribute('position',new THREE.Float32BufferAttribute(points,3));sg.setAttribute('uv',new THREE.Float32BufferAttribute(uv,2));sg.setIndex(ix);sg.computeVertexNormals();const sm=new THREE.MeshStandardMaterial({color:pirate?'#303c39':'#f5e9c9',side:THREE.DoubleSide,roughness:1});const sail=mesh(sg,sm,ship);sails.push(sail);if(!pirate&&k===1&&z>.1){const emblem=mesh(new THREE.RingGeometry(.2,.27,6),new THREE.MeshBasicMaterial({color:'#a16843',side:THREE.DoubleSide}),ship,0,yy+.35,z+.75);emblem.rotation.z=Math.PI/6;}}
 for(const side of [-1,1]){line(ship,[[0,h+1,z],[side*1.2,1.15,z+.8]],'#5f503b');line(ship,[[0,h+1,z],[side*.9,1.15,z-1.1]],'#5f503b');}const flag=box(ship,.9,.36,.018,pirate?palette.dark:mat('#517f7d'),.42,h+.8,z);}
